#pragma once

/// \file cyk_parser.hpp
/// \brief The CYK (Cocke-Younger-Kasami) algorithm: decide whether a string is
///        generated by a context-free grammar in Chomsky normal form.
///
/// Parsing a general context-free grammar looks like it might need backtracking, but
/// the CYK algorithm does it in guaranteed \f$O(n^3\,|G|)\f$ time by *dynamic
/// programming* over substrings. The grammar must be in *Chomsky normal form* -- every
/// rule is either \f$A\to BC\f$ (two nonterminals) or \f$A\to a\f$ (one terminal). CYK
/// fills a triangular table where entry \f$(i,\ell)\f$ holds every nonterminal that can
/// derive the length-\f$\ell\f$ substring starting at \f$i\f$: length-1 cells come from
/// the terminal rules, and a longer cell is filled by trying every split point and
/// every binary rule \f$A\to BC\f$ with \f$B\f$ deriving the left part and \f$C\f$ the
/// right. The string is in the language iff the start symbol reaches the full-length
/// top cell. It is the textbook parser for arbitrary CFGs and the recognition core
/// behind probabilistic (inside-outside) parsing.

#include <array>
#include <cstddef>
#include <set>
#include <string>
#include <unordered_map>
#include <vector>

namespace datamunge::algorithms {

/// A context-free grammar in Chomsky normal form (nonterminals are integer ids).
struct CNFGrammar {
    int                                         start = 0;  ///< Start symbol id.
    std::unordered_map<char, std::vector<int>>  unary;      ///< terminal -> nonterminals deriving it (A -> a).
    std::vector<std::array<int, 3>>             binary;     ///< rules {A, B, C} meaning A -> B C.
};

/// \brief Recognize whether \p s is generated by CNF grammar \p g (CYK dynamic program).
///
/// \return true iff the start symbol derives the whole string.
inline bool cyk_recognize(const CNFGrammar& g, const std::string& s) {
    const std::size_t n = s.size();
    if (n == 0) return false;
    // table[len-1][i] = set of nonterminals deriving s[i .. i+len-1].
    std::vector<std::vector<std::set<int>>> table(n, std::vector<std::set<int>>(n));

    for (std::size_t i = 0; i < n; ++i) {
        const auto it = g.unary.find(s[i]);
        if (it != g.unary.end())
            for (int nt : it->second) table[0][i].insert(nt);
    }

    for (std::size_t len = 2; len <= n; ++len)
        for (std::size_t i = 0; i + len <= n; ++i)
            for (std::size_t split = 1; split < len; ++split) {
                const auto& left  = table[split - 1][i];
                const auto& right = table[len - split - 1][i + split];
                if (left.empty() || right.empty()) continue;
                for (const auto& rule : g.binary)
                    if (left.count(rule[1]) && right.count(rule[2])) table[len - 1][i].insert(rule[0]);
            }

    return table[n - 1][0].count(g.start) > 0;
}

}  // namespace datamunge::algorithms
